<script setup lang="ts">
import { onMounted, ref } from 'vue'; import { Button, Empty, Spin, message } from 'ant-design-vue'; import { useRouter } from 'vue-router'; import InterviewRecordCard from '@/features/interview/components/InterviewRecordCard.vue'; import { listInterviews, type InterviewRecord } from '@/features/interview/api/interview-flow-api'; import { toApiError } from '@/shared/api/errors'
const router=useRouter(), items=ref<InterviewRecord[]>([]), cursor=ref<string|null>(null), loading=ref(false)
onMounted(load); async function load(){loading.value=true;try{const page=await listInterviews(cursor.value??undefined);items.value.push(...page.items);cursor.value=page.nextCursor}catch(e){message.error(toApiError(e).message)}finally{loading.value=false}}
function open(item:InterviewRecord){if(item.stage==='PREPARING'||item.stage==='READY')void router.push(`/app/interviews/${item.interviewId}/ready`);else if(item.stage==='INTERVIEWING')void router.push(`/app/interviews/${item.interviewId}/session`);else void router.push(`/app/interviews/${item.interviewId}/report`)}
</script>
<template><section class="records"><header><div><p class="eyebrow">INTERVIEW HISTORY</p><h2>面试记录</h2><p>从 MySQL 恢复未完成面试，或查看已发布的正式报告。</p></div><Button type="primary" @click="router.push('/app/interviews')">开始新面试</Button></header><Spin :spinning="loading"><div v-if="items.length" class="grid"><InterviewRecordCard v-for="item in items" :key="item.interviewId" :record="item" @open="open"/></div><Empty v-else-if="!loading" description="还没有面试记录"/></Spin><Button v-if="cursor" :loading="loading" @click="load">加载更多</Button></section></template>
<style scoped>.records{display:grid;gap:24px}.records header{display:flex;justify-content:space-between;align-items:flex-start}.records h2{margin:4px 0;font-size:32px;color:#0b1740}.records header p:last-child{color:var(--cf-color-text-muted)}.eyebrow{color:var(--cf-color-primary);font-weight:750}.grid{display:grid;grid-template-columns:repeat(3,1fr);gap:16px}</style>
